            hook: [4, -1, 3, 4, -1, 2, 3, -1, 2, -1, 1, 2, -1, 0, 1, -1, 4, -1, 3, 4, -1, 5, 6, -1, 5, 4, 3, -1, 2, -1, 1, -1],
