            hook: [3, -1, -1, 3, 4, -1, 3, -1, 2, -1, 0, -1, 2, 3, -1, -1, 3, -1, -1, 3, 5, -1, 4, 3, 2, -1, 3, -1, 0, -1, -1, -1],
