            const wet = new THREE.Mesh(new THREE.PlaneGeometry(340, 10.5), new THREE.MeshStandardMaterial({ color: 0xc49e68, roughness: 0.16, metalness: 0.16 }));
            wet.rotation.x = -Math.PI / 2; wet.position.set(0, 0.008, -59.5);
