            S.collider(-4.1, 0, 3.9, 4.1, 3, 4.2);
            const sign = A.sign('♥ SWEETHEART SHORE ♥', 3.8, 0.6, { bg: '#fdf2f8', color: '#db2777', borderColor: '#f472b6', size: 0.52 });
            sign.position.set(0, 2.55, 4.0);
