            const buoy = new THREE.Mesh(new THREE.TorusGeometry(0.28, 0.08, 8, 18), std(0xf43f5e, 0.4)); buoy.position.set(-1.05, 3.1, 0); buoy.rotation.y = Math.PI / 2;
            buoyMesh = buoy;
