        heroLabel: 'FLIGHT CIRCUIT • 5 MAPS + SANDBOX', duration: 120, stars: [1800, 3600, 5600, 8200],
        standardWeapon: 'intervention', lockWeapon: true, infiniteMag: true, maxScopeTime: 1.0, customMusic: true,
