                    g.strokeStyle = col; g.lineWidth = 14; g.strokeRect(7, 7, w - 14, h - 14);
                    g.fillStyle = col; g.font = '900 78px sans-serif'; g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText(ch, w / 2, h / 2 + 4);
