        echo_panels:      { sky: ['#090d26', '#2e1065', '#4c1d95'], bloom: '#a78bfa', scene: 'cyber',   label: 'MEMORY MATRIX', bx: 0.58, by: 0.30 },
        switchyard:       { sky: ['#451a03', '#78350f', '#d97706'], bloom: '#fbbf24', scene: 'canyon',  label: 'FRONTIER RAILS', bx: 0.70, by: 0.28 },
